<?php require '../config/database.php';require '../includes/functions.php';require_login(); if (!is_customer() && !is_admin()) { http_response_code(403); exit('Forbidden.'); }$id=(int)($_GET['id']??0);$sql="SELECT b.*,r.name room_name,r.image_url,u.name guest_name,u.email FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN users u ON u.id=b.user_id WHERE b.id=?";if(!is_admin())$sql.=" AND b.user_id=".((int)$_SESSION['user']['id']);$st=$pdo->prepare($sql);$st->execute([$id]);$b=$st->fetch();if(!$b){http_response_code(404);exit('Booking not found');}$page_title='Booking '.$b['reference_no'];include '../includes/header.php';?><div class="container page-hero"><h1>Booking <?=e($b['reference_no'])?></h1><p><span class="badge <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span></p></div><section style="padding-top:10px"><div class="container two-col"><div class="card" style="padding:24px"><h2><?=e($b['room_name'])?></h2><img src="<?=e($b['image_url'])?>" style="width:100%;max-height:320px;object-fit:cover;border-radius:14px"><div class="summary-line"><span>Guest</span><strong><?=e($b['guest_name'])?></strong></div><div class="summary-line"><span>Booked on</span><strong><?=e(date('M j, Y g:i A',strtotime($b['created_at'])))?></strong></div><div class="summary-line"><span>Check-in</span><strong><?=e($b['check_in'])?></strong></div><div class="summary-line"><span>Check-out</span><strong><?=e($b['check_out'])?></strong></div><div class="summary-line"><span>Guests</span><strong><?=e($b['guests'])?></strong></div></div><div class="card booking-box"><h3>Payment summary</h3><div class="summary-line"><span>Nights</span><strong><?=e($b['nights'])?></strong></div><div class="summary-line"><span>Payment</span><strong><?=e(ucfirst($b['payment_status']))?></strong></div><div class="summary-line total"><span>Total</span><span>₱<?=number_format($b['total_amount'],2)?></span></div><?php if(is_customer()&&in_array($b['status'],['pending','confirmed'])):?><form method="post" action="<?=url('booking/cancel.php')?>" data-confirm="Cancel this reservation? This releases the room for the affected dates." data-confirm-title="Cancel booking"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-danger" style="width:100%">Cancel booking</button></form><?php endif;?></div></div></section><?php include '../includes/footer.php';?>